// SegmentedControl, AS GRAPH SOURCE (#3678, epic #3604) — a pure shared/ui control authored as DATA. Its
// `provides: "@/shared/ui/controls/SegmentedControl"` makes the runtime loader vendor THIS over the bundled module (registered code
// is the fallback). Transcribed verbatim; deps stay registered code.
// `loading` renders a skeleton pill group; `error` renders an inline error note (checked first); an
// empty `options` array renders a distinct dashed "no options" placeholder instead of a blank bar.
import type { ReactNode } from "react";

export interface SegOption {
  label: ReactNode;
  /** Whether this option is currently active. */
  on: boolean;
  onClick: () => void;
  /** On-state colour. Default "accent". */
  tone?: "accent" | "allow" | "ask" | "deny";
  /** Show a leading dot in the current colour. */
  dot?: boolean;
  title?: string;
}

export interface SegmentedControlProps {
  options: SegOption[];
  /** "padded" (default) = gapped pill buttons in a padded container; "joined" = a tight shared-border bar. */
  variant?: "padded" | "joined";
  /** Button height: "sm" (22px, default) or "md" (24px). */
  size?: "sm" | "md";
  /** Optional leading label (e.g. "scope"). */
  label?: ReactNode;
  className?: string;
  /** Render a skeleton pill group instead of the real options. */
  loading?: boolean;
  /** Render an error note instead of the real options — a message string, or true for a generic one. Takes priority over loading. */
  error?: string | boolean;
}

// A small sample so a standalone preview (no page feeding real options) shows real pills instead of
// an empty bar.
const SAMPLE_OPTIONS: SegOption[] = [
  { label: "Day", on: false, onClick: () => {} },
  { label: "Week", on: true, onClick: () => {} },
  { label: "Month", on: false, onClick: () => {} },
];

/** SegmentedControl — the one mutually-exclusive / multi-toggle button group: the control-vocabulary
 *  primitive that absorbs `.scope` · `.seg` · `.tri` · `.pill-group` (#1874). Each option owns its
 *  on-state + click, so it serves single-select and multi-select alike; `tone` covers the
 *  allow/ask/deny tri-states. */
export function SegmentedControl({ options = SAMPLE_OPTIONS, variant = "padded", size = "sm", label, className, loading, error }: SegmentedControlProps) {
  if (error) {
    return (
      <div className={"seg-ctl" + (className ? ` ${className}` : "")} style={{ color: "var(--danger)", fontSize: 11.5 }}>
        {typeof error === "string" ? error : "Couldn't load options"}
      </div>
    );
  }

  if (loading) {
    return (
      <div className={"seg-ctl" + (className ? ` ${className}` : "")} style={{ display: "flex", gap: 6 }}>
        {[1, 2, 3].map((i) => (
          <div key={i} className="skeleton" style={{ width: 48, height: size === "md" ? 24 : 22, borderRadius: 999, background: "var(--bg-elev)" }} />
        ))}
      </div>
    );
  }

  const opts = options ?? [];

  return (
    <div className={"seg-ctl" + (className ? ` ${className}` : "")}>
      {label != null && <span className="seg-ctl-label">{label}</span>}
      {opts.length === 0 ? (
        <span style={{ fontSize: 11.5, color: "var(--fg-dim)", border: "1px dashed var(--border)", borderRadius: 999, padding: "3px 10px" }}>
          no options
        </span>
      ) : (
        <div className={`seg-grp ${variant} size-${size}`}>
          {opts.map((o, i) => (
            <button
              key={i}
              type="button"
              title={o.title}
              className={"seg-btn tone-" + (o.tone ?? "accent") + (o.on ? " on" : "")}
              onClick={o.onClick}
            >
              {o.dot && <span className="seg-dot" />}
              {o.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

